function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#0a0e18', Brick='#3d4f6f', BrickLt='#5a6f94', Mortar='#1a2233';
  px(0,0,32,32,Mortar);
  const rows=[[0,0],[0,8],[0,16],[0,24]];
  rows.forEach((r,i)=>{
    const off=i%2?4:0;
    for (let x=-4+off;x<32;x+=10) {
      px(x,r[1],9,7,Brick); px(x,r[1],9,1,BrickLt); px(x,r[1]+6,9,1,O);
    }
  });

}
